127	 * Base premium for a group of alike items. A block rate applies only when a
128	 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
129	 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
130	 */
131	const basePremiumOfGroup = (type: string, count: number): number => {
132	  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
133	    return COMPONENT_BLOCK_PREMIUM;
134	  }
135	  return count * basePremiumOfType(type);
136	};
