138	const CURSE_SURCHARGE_PERCENT = 50;
139	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
140	const HIGH_ENCHANTMENT_MIN_LEVEL = 5;
141	
142	/**
143	 * Whether an item carries an enchantment at or above the surcharge threshold.
144	 * Components (runes, moonstones) have no enchantment field at all; an absent
145	 * enchantment is not a level of 0, it is the absence of the property, and so
146	 * never qualifies. Stated as an explicit undefined check rather than a numeric
147	 * default so the reason reads as "unenchanted", not "enchanted to zero".
148	 */
149	const isHighlyEnchanted = (item: Item): boolean =>
150	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_MIN_LEVEL;
151	
152	/**
153	 * Item-specific surcharges are a percentage of the affected item's OWN base
154	 * premium, not of the policy total. They are summed alongside the policy-wide
