276	 * (1000 - 100) halved.
277	 */
278	const payoutForDamage = (damage: Damage, items: Item[]): number => {
279	  const item = damagedItem(damage, items);
280	  const enchantment = item?.enchantment;
281	  const reimbursed =
282	    enchantment !== undefined &&
283	    enchantment >= HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
284	      ? percentOf(damage.amount, HIGH_ENCHANTMENT_CLAUSE_PERCENT)
285	      : damage.amount;
286	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
287	};
288	
289	/**
290	 * A claim's effect on its policy: what is paid now and what the policy has
291	 * left afterwards. Pure — the caller is responsible for storing the new
292	 * remaining cap, so the arithmetic can be read (and later clipped to the cap)
293	 * without tracing who mutated what.
294	 */
295	const claimOutcome = (incident: Incident, policy: Policy): ClaimResult => {
296	  const payout = incident.damages.reduce(
297	    (total, damage) => total + payoutForDamage(damage, policy.items),
298	    0,
299	  );
300	  return { payout, remainingCap: policy.remainingCap - payout };
301	};
302	
303	/**
304	 * Where a step sits in the scenario walk. The two ordinals are genuinely
305	 * different facts and must not be collapsed: `index` is the step's own
306	 * zero-based position, which is how a later claim names its policy, while
307	 * `quoteOrdinal` counts QUOTE steps only. In [quote, claim, quote] the last
308	 * step has index 2 but quote ordinal 1 — using either in place of the other
309	 * would misprice the follow-up discount.
310	 */
311	interface StepPosition {
312	  index: number;
313	  quoteOrdinal: number;
314	}
315	
316	/** The mutable state carried along one scenario: the policies quotes create. */
317	interface ScenarioWalk {
318	  customer: Customer;
319	  policies: Map<number, Policy>;
320	}
