322	const runStep = (
323	  step: Step,
324	  position: StepPosition,
325	  walk: ScenarioWalk,
326	): StepResult => {
327	  if (step.op === "quote") {
328	    walk.policies.set(position.index, policyFor(step.items));
329	    return quoteResult(step.items, walk.customer, position.quoteOrdinal);
330	  }
331	  const policy = walk.policies.get(step.policy);
332	  if (policy === undefined) {
333	    throw new Error(`No policy created by step ${step.policy}`);
334	  }
335	  const outcome = claimOutcome(step.incident, policy);
336	  policy.remainingCap = outcome.remainingCap;
337	  return outcome;
338	};
