340	export const runScenario = (scenario: Scenario): ScenarioResults => {
341	  const walk: ScenarioWalk = {
342	    customer: scenario.customer,
343	    policies: new Map<number, Policy>(),
344	  };
345	  let quoteOrdinal = FIRST_QUOTE_ORDINAL;
346	  const results = scenario.steps.map((step, index) => {
347	    const result = runStep(step, { index, quoteOrdinal }, walk);
348	    if (step.op === "quote") quoteOrdinal += 1;
349	    return result;
350	  });
351	  return { results };
352	};
